@page "/apply"
@namespace sv_bb90d86f706d4f64bc11ad5f535d4f21.Components.Pages.Apply
@using sv_bb90d86f706d4f64bc11ad5f535d4f21.Services
@inject IApplicationService ApplicationService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    <StepIndicator CurrentStep="@_currentStep" OnStepClicked="GoToStep" />

    @switch (_currentStep)
    {
        case 1:
            <PersonalInfoStep FullName="@_fullName"
                              Email="@_email"
                              Phone="@_phone"
                              Address="@_address"
                              ValidateEmail="ApplicationService.ValidateEmailAsync"
                              OnNext="HandlePersonalNext" />
            break;

        case 2:
            <WorkHistoryStep Entries="@_workEntries"
                             OnNext="HandleWorkNext"
                             OnBack="() => GoToStep(1)" />
            break;

        case 3:
            <ReferencesStep References="@_references"
                            OnNext="HandleReferencesNext"
                            OnBack="() => GoToStep(2)" />
            break;

        case 4:
            <CoverLetterStep CoverLetter="@_coverLetter"
                             OnNext="HandleCoverLetterNext"
                             OnBack="() => GoToStep(3)" />
            break;

        case 5:
            <ReviewStep Personal="@(new PersonalInfoStep.PersonalInfoResult(_fullName, _email, _phone, _address))"
                        WorkEntries="@_workEntries"
                        References="@_references"
                        CoverLetter="@_coverLetter"
                        OnEdit="GoToStep"
                        OnBack="() => GoToStep(4)"
                        OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private int _currentStep = 1;

    // Step 1
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";

    // Step 2
    private List<WorkHistoryStep.EntryModel> _workEntries = new() { new() };

    // Step 3
    private List<ReferencesStep.ReferenceModel> _references = new() { new(), new() };

    // Step 4
    private string _coverLetter = "";

    private void HandlePersonalNext(PersonalInfoStep.PersonalInfoResult result)
    {
        _fullName = result.FullName;
        _email = result.Email;
        _phone = result.Phone;
        _address = result.Address;
        _currentStep = 2;
    }

    private void HandleWorkNext(List<WorkHistoryStep.EntryModel> entries)
    {
        _workEntries = entries;
        _currentStep = 3;
    }

    private void HandleReferencesNext(List<ReferencesStep.ReferenceModel> references)
    {
        _references = references;
        _currentStep = 4;
    }

    private void HandleCoverLetterNext(string coverLetter)
    {
        _coverLetter = coverLetter;
        _currentStep = 5;
    }

    private void GoToStep(int step)
    {
        _currentStep = step;
    }

    private async Task<int> SubmitApplication()
    {
        var personal = new PersonalInfo(_fullName, _email, _phone, _address);
        var workHistory = new WorkHistory(
            _workEntries.Select(e => new WorkEntry(
                e.Company, e.Title, e.StartDate ?? DateTime.MinValue, e.EndDate, e.Description
            )).ToList()
        );
        var references = _references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
        var application = new JobApplication(personal, workHistory, references, _coverLetter);

        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

